sql.seed.sql:
CREATE TABLE IF NOT EXISTS public.local_051_fixture(actor uuid,org uuid,location jsonb);
TRUNCATE local_051_fixture;
DO $seed$ DECLARE actor uuid:=gen_random_uuid(); result jsonb; org uuid; location jsonb; BEGIN
 INSERT INTO auth.users(id) VALUES(actor);
 result:=save_organisation_with_partner(NULL,jsonb_build_object('name','concurrent-local-'||actor::text,'type','reward_partner'));org:=(result->'organisation'->>'id')::uuid;
 location:=save_partner_location(org,jsonb_build_object('name','Original','address','Synthetic','status','draft','rewardIds','[]'::jsonb),actor,'concurrent-seed');
 INSERT INTO local_051_fixture VALUES(actor,org,location);
END $seed$;

sql.writer-a.sql:
SET application_name='movrr051-edit-a';
BEGIN;
DO $writer$ DECLARE f local_051_fixture; BEGIN SELECT * INTO f FROM local_051_fixture;
 PERFORM save_partner_location(f.org,jsonb_build_object('id',f.location->>'id','expectedUpdatedAt',f.location->>'updated_at','name','Winner','address','Synthetic','status','draft','rewardIds','[]'::jsonb),f.actor,'writer-a');
 PERFORM pg_sleep(3);
END $writer$;
COMMIT;

sql.writer-b.sql:
DO $contender$ DECLARE f local_051_fixture; caught boolean:=false; BEGIN SELECT * INTO f FROM local_051_fixture;
 BEGIN PERFORM save_partner_location(f.org,jsonb_build_object('id',f.location->>'id','expectedUpdatedAt',f.location->>'updated_at','name','Loser','address','Synthetic','status','draft','rewardIds','[]'::jsonb),f.actor,'writer-b');
 EXCEPTION WHEN OTHERS THEN IF SQLERRM='Location version conflict' THEN caught:=true; ELSE RAISE; END IF; END;
 IF NOT caught THEN RAISE EXCEPTION 'Concurrent stale writer accepted'; END IF;
 IF (SELECT name FROM reward_partner_location WHERE id=(f.location->>'id')::uuid)<>'Winner' OR (SELECT count(*) FROM partner_location_audit WHERE location_id=(f.location->>'id')::uuid)<>2 THEN RAISE EXCEPTION 'Concurrent lost update/audit mismatch'; END IF;
 RAISE NOTICE 'PASS two overlapping native PostgreSQL sessions: one edit committed, stale edit rejected';
END $contender$;
